select *
from b_sushang_call_record_data
where local_id = #{local_id}
  and cust_num = #{cust_num}
  and call_time <= #{minDealTime} 
order by call_time desc limit 1

select *
from b_sushang_call_record_data
where local_id = #{local_id}
  and cust_num = #{cust_num}
  and call_time >= #{callTime}

Select b.*
From (select a.*, row_number() over(partition by cust_num order by call_time asc) as rn
From b_sushang_call_record_data a
where local_id =#{local_id}
and  call_time >= #{beginDate} and call_time <= #{endDate}
) b
Where b.rn = 1

    and b.id > #{indexId}

order by b.id asc limit #{pageSize};
